"""LO model whose equations are generated by FRGscalarMSR (Mathematica).

The generated module (``ExportPython``, contract: FRGscalarMSR ``docs/handoff/BMWflow_LO.md``) holds the
model: kernels of the loop integrals, the eta system, the linear part and beta, already written in BMWflow's
coupling g. This adapter owns only the numerics: grids, splines, the integration measure, the p = 0 fill of
rows divided by p^2, the eta linear solve.
"""
import importlib.util
import itertools
import types
from pathlib import Path

import numpy as np

from .. import flow_dataclasses
from .model_base import ModelBase
from .maths_utils import GaussLegendre, GaussLegendre2D_NLO

CONTRACT_VERSION = 2
_KERNELS = ("linear", "loop", "eta_matrix", "eta_vector", "beta")
_counter = itertools.count()


def load_generated(module) -> types.ModuleType:
    """Returns the generated module: `module` is a path to a ``.py`` file or an already imported module."""
    if isinstance(module, types.ModuleType):
        return module
    path = Path(module)
    if path.suffix != ".py" or not path.is_file():
        raise FileNotFoundError(f"Generated module not found (expected a .py file): {path}")
    spec = importlib.util.spec_from_file_location(f"flow_generated_{path.stem}_{next(_counter)}", path)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def check_contract(mod: types.ModuleType, approximation: str, dim: int):
    """Raises if the generated module does not follow the contract this adapter implements."""
    name = getattr(mod, "__file__", mod.__name__)
    version = getattr(mod, "CONTRACT_VERSION", None)
    if version != CONTRACT_VERSION:
        raise ValueError(f"{name}: CONTRACT_VERSION {version}, this BMWflow reads {CONTRACT_VERSION}: "
                         f"regenerate it with FRGscalarMSR's ExportPython (or update BMWflow).")
    missing = [k for k in ("FUNCTIONS", "ETAS", "COUPLINGS", "SHAPES", "P2_DIVIDED", "FIXED_DIMENSION",
                           "APPROXIMATION", "MODEL", *_KERNELS) if not hasattr(mod, k)]
    if missing:
        raise ValueError(f"{name}: missing {missing}")
    if mod.APPROXIMATION != "LO" or approximation != "LO":
        raise ValueError(f"Generated models are LO only (module: {mod.APPROXIMATION}, requested: {approximation}).")
    if mod.FIXED_DIMENSION is not None and mod.FIXED_DIMENSION != dim:
        raise ValueError(f"{name} was derived in d = {mod.FIXED_DIMENSION}, requested dim = {dim}.")
    if tuple(mod.COUPLINGS) != ("g",):
        raise ValueError(f"{name}: COUPLINGS must be ('g',), got {mod.COUPLINGS}.")
    n_f = len(mod.FUNCTIONS)
    if len(mod.ETAS) != n_f or len(mod.P2_DIVIDED) != n_f:
        raise ValueError(f"{name}: FUNCTIONS, ETAS and P2_DIVIDED must have the same length.")


class ModelGenerated(ModelBase):
    """LO model loaded from a module generated by FRGscalarMSR.

    The flowing functions are ``module.FUNCTIONS`` (n_f is taken from it) and the etas ``module.ETAS``,
    in the same order; g is BMWflow's scalar coupling, as in the hand-written models.
    """

    _print_excluded = ("cos_broad", "rq_shapes", "rq__shapes", "rQ_shapes", "r_eta", "r__eta", "regulators")

    def __init__(
            self,
            module,
            approximation: str,
            dim: int,
            params_grid_external: flow_dataclasses.ParamsGridExternal,
            params_grid_internal: flow_dataclasses.ParamsGridInternal,
            r, r_,
            Integral_extrapol='const',
            regulators=None,
            fixed_etas=None):
        """

        Parameters
        ----------
        module: str, Path or module
            The generated ``.py`` file (or the module once imported).
        r, r_: callable
            Regulator shape r(q) and dr/d(q^2), used for every shape in ``module.SHAPES``
            that `regulators` does not name.
        Integral_extrapol: str
            "const" or "quad": how rows divided by p^2 (``module.P2_DIVIDED``) are filled at p = 0:
            the value at p[1], or a + b p^2 through p[1], p[2].
        regulators: dict, optional
            {shape name: (r, r_)} for shapes that differ from (r, r_).
        fixed_etas: dict, optional
            {eta name: value} for etas held fixed instead of solved; the normalisation f_X(0) = 1 of the
            corresponding function is then dropped and f_X(0) flows.
        """
        self.module = load_generated(module)
        check_contract(self.module, approximation, dim)
        if Integral_extrapol not in ('const', 'quad'):
            raise ValueError('Integral_extrapol must be either "const" or "quad".')
        self.Integral_extrapol = Integral_extrapol

        self.shapes = tuple(self.module.SHAPES)
        regulators = dict(regulators or {})
        unknown = set(regulators) - set(self.shapes)
        if unknown:
            raise ValueError(f"regulators names unknown shapes {sorted(unknown)}; the module has {self.shapes}.")
        self.regulators = {s: regulators.get(s, (r, r_)) for s in self.shapes}
        self.p2_divided = tuple(self.module.P2_DIVIDED)
        etas = tuple(self.module.ETAS)
        fixed_etas = dict(fixed_etas or {})
        unknown = set(fixed_etas) - set(etas)
        if unknown:
            raise ValueError(f"fixed_etas names unknown etas {sorted(unknown)}; the module has {etas}.")
        self.fixed_etas = {etas.index(k): float(v) for k, v in fixed_etas.items()}

        self._g = None  # g of the last Integral_upd, used by the linear part in f_rhs_calc
        super().__init__(len(self.module.FUNCTIONS), approximation, dim,
                         params_grid_external, params_grid_internal, r, r_)

    ##########################################################################
    # Methods : init
    ##########################################################################

    def _init_calc(self):
        super()._init_calc()
        regs = [self.regulators[s] for s in self.shapes]

        ## Loop integrand: shape (p, w, q, theta)
        self.cos_broad = np.cos(self.theta)[np.newaxis, np.newaxis, np.newaxis, :]
        self.loop_shape = np.broadcast_shapes(self.Q_broad.shape, self.cos_broad.shape)
        self.rq_shapes = tuple(rr(self.q_broad) for rr, _ in regs)
        self.rq__shapes = tuple(rr_(self.q_broad) for _, rr_ in regs)
        self.rQ_shapes = tuple(rr(self.Q_broad) for rr, _ in regs)

        ## Eta system: shape (q,), measure v_d q^(d-1) dq
        self.r_eta = tuple(rr(self.q) for rr, _ in regs)
        self.r__eta = tuple(rr_(self.q) for _, rr_ in regs)
        self.eta_weight = self.vdim * self.wq * self.q ** (self.dim - 1)

    ##########################################################################
    # Methods : calc
    ##########################################################################

    def Integral_pfixed_dD_LO(self, g, eta):
        """Loop integrals I_X(p), shape (n_f, Np, Nw), without the p = 0 fill:
        I_X = v_{d-1}/(2 pi) Int dq q^(d-1) Int dtheta sin^(d-2)(theta) loop_X."""
        fq = tuple(self.fq[i, None, None, :, None] for i in range(self.n_f))
        fQ = tuple(self.fQ[i] for i in range(self.n_f))
        with np.errstate(divide='ignore', invalid='ignore'):
            F = self.module.loop(self.p_broad, self.q_broad, self.cos_broad, self.Q_broad2, fq, fQ,
                                 self.rq_shapes, self.rq__shapes, self.rQ_shapes, eta, (g,), self.dim)
            I = [self.vdim1 / (2 * np.pi) *
                 GaussLegendre2D_NLO(self.wq, self.wtheta, self.Jdim1,
                                     self.sin_d2_broad * np.broadcast_to(Fx, self.loop_shape))
                 for Fx in F]
        return np.array(I)

    def Integral_pfixed_dD_NLO(self, g, eta):
        raise NotImplementedError("Generated models are LO only.")

    def f_rhs_logder_calc_NLO(self, eta):
        raise NotImplementedError("Generated models are LO only.")

    def Integral_upd(self, g, eta):
        """Calculates the loop integrals and fills the p = 0 row of the rows divided by p^2."""
        self._g = g
        self.Integral = self.Integral_pfixed(g, eta)
        for i, n in enumerate(self.p2_divided):
            if n > 0:
                self._fill_p0(self.Integral[i], self.Integral_extrapol)

    def f_rhs_calc(self, eta, f):
        """d_s f = linear + I (uses the g of the last Integral_upd)."""
        p = self.p[:, None]
        fprime = tuple(np.array([spl.derivative()(self.p) for spl in self.f_spl[i]]).T for i in range(self.n_f))
        lin = self.module.linear(p, tuple(f), fprime, eta, (self._g,), self.dim)
        return np.array([np.broadcast_to(x, self.external_grid_shape) for x in lin]) + self.Integral

    def eta_calc(self, g):
        """Solves sum_Y (delta_XY + <M[X][Y]>) eta_Y = -<b[X]>, <.> = v_d Int dq q^(d-1) (.).
        Rows of the etas in ``fixed_etas`` are dropped and their values moved to the right-hand side."""
        args = (self.q, tuple(self.fq), tuple(self.fq_), self.r_eta, self.r__eta, (g,), self.dim)
        M = self.module.eta_matrix(*args)
        b = self.module.eta_vector(*args)
        avg = lambda x: GaussLegendre(self.eta_weight, np.broadcast_to(x, self.q.shape))
        Mbar = np.array([[avg(M[X][Y]) for Y in range(self.n_f)] for X in range(self.n_f)])
        bbar = np.array([avg(b[X]) for X in range(self.n_f)])
        A, rhs = np.eye(self.n_f) + Mbar, -bbar
        if not self.fixed_etas:
            return np.linalg.solve(A, rhs)
        X = np.array(sorted(self.fixed_etas), dtype=int)
        F = np.array([i for i in range(self.n_f) if i not in self.fixed_etas], dtype=int)
        eta = np.zeros(self.n_f)
        eta[X] = [self.fixed_etas[i] for i in X]
        if F.size:
            eta[F] = np.linalg.solve(A[np.ix_(F, F)], rhs[F] - Mbar[np.ix_(F, X)] @ eta[X])
        return eta

    def g_rhs_calc(self, g, eta):
        return self.module.beta((g,), eta, self.dim)[0]

    def calc_upd(self):
        self.calc_upd_LO()
